const p = $json.body ?? $json;
const d = p.data?.FIELDS ?? p.data ?? p;
const expectedSecret = String($env.BITRIX_WEBHOOK_SECRET || '').trim();
const suppliedSecret = String(
  $json.headers?.['x-webhook-secret'] ||
  $json.query?.secret ||
  p.secret ||
  p.auth?.application_token ||
  ''
).trim();

function pick(...keys) {
  for (const key of keys) {
    const variants = [key, key.toLowerCase(), 'data[' + key + ']', 'data[' + key.toLowerCase() + ']'];
    for (const variant of variants) {
      if (d?.[variant] !== undefined && d[variant] !== '') return d[variant];
      if (p?.[variant] !== undefined && p[variant] !== '') return p[variant];
    }
  }
  return undefined;
}

function numberFromEnv(name, fallback) {
  const value = Number($env[name] ?? fallback);
  return Number.isFinite(value) ? value : fallback;
}

function moscowHour(value) {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Moscow',
    hour: '2-digit',
    hour12: false,
  }).formatToParts(date);
  const hour = Number(parts.find((part) => part.type === 'hour')?.value);
  return Number.isFinite(hour) ? hour : null;
}

const activityId = pick('CRM_ACTIVITY_ID', 'ACTIVITY_ID', 'activity_id', 'activityId');
const durationRaw = pick('CALL_DURATION', 'DURATION', 'duration');
const duration = durationRaw === undefined ? null : Number(durationRaw);
const failedCode = String(pick('CALL_FAILED_CODE', 'FAILED_CODE', 'CALL_STATUS_CODE') ?? '').trim();
const eventDate = pick('CALL_END_DATE', 'CALL_START_DATE', 'DATE', 'date');
const failedPrefixes = ['304', '404', '480', '486', '500', '603'];
const hasFailedCode = failedPrefixes.some((code) => failedCode === code || failedCode.startsWith(code + '-'));
const minimumDuration = numberFromEnv('MIN_CALL_DURATION_SECONDS', 30);
const startHour = numberFromEnv('PROCESSING_START_HOUR_MSK', 0);
const endHour = numberFromEnv('PROCESSING_END_HOUR_MSK', 24);
const hourMsk = moscowHour(eventDate);
const withinWindow = hourMsk !== null && hourMsk >= startHour && hourMsk < endHour;
const tokenValid = expectedSecret.length >= 16 && suppliedSecret === expectedSecret;
const validActivity = Boolean(activityId) && String(activityId).trim() !== '0';
const longEnough = Number.isFinite(duration) && duration >= minimumDuration;

return [{
  json: {
    activityId,
    duration,
    failedCode,
    eventDate,
    hourMsk,
    tokenValid,
    isSuccessfulCallCandidate: tokenValid && validActivity && longEnough && !hasFailedCode && withinWindow,
  },
}];

const activity = $('Get Activity').first().json.result ?? {};
const statsResponse = $json ?? {};
const statsRows = Array.isArray(statsResponse.result) ? statsResponse.result : [];
const stat = statsRows[0] ?? {};

function walk(value, path = '') {
  const out = [];
  if (value === null || value === undefined) return out;
  if (typeof value === 'string') out.push({ path, value });
  else if (Array.isArray(value)) value.forEach((v, i) => out.push(...walk(v, path + '[' + i + ']')));
  else if (typeof value === 'object') Object.entries(value).forEach(([k, v]) => out.push(...walk(v, path ? path + '.' + k : k)));
  return out;
}

function looksLikeRecordingUrl(value) {
  const s = String(value || '');
  const lower = s.toLowerCase();
  const isUrl = lower.startsWith('http://') || lower.startsWith('https://');
  const hasHint = lower.includes('record') || lower.includes('audio') || lower.includes('call') || lower.includes('download') || lower.includes('.mp3') || lower.includes('.m4a') || lower.includes('.wav') || lower.includes('.ogg');
  return isUrl && hasHint;
}

const strings = [...walk(stat), ...walk(activity)];
const recordingUrl =
  stat.CALL_RECORD_URL ||
  stat.CALL_RECORD ||
  stat.RECORD_URL ||
  activity.CALL_RECORD_URL ||
  (strings.find(({ value }) => looksLikeRecordingUrl(value)) || {}).value ||
  '';

const recordingFileId =
  stat.CALL_WEBDAV_ID ||
  stat.RECORD_FILE_ID ||
  stat.FILE_ID ||
  activity.CALL_WEBDAV_ID ||
  activity.RECORD_FILE_ID ||
  activity.FILE_ID ||
  '';

return [{ json: { recordingUrl, recordingFileId, stat, activityId: $('Normalize Bitrix Payload').first().json.activityId } }];

const meta = $('Resolve Recording Metadata').first().json;
const disk = $('Get Disk File Info').first().json ?? {};
const diskResult = disk.result ?? {};
const diskUrl = diskResult.DOWNLOAD_URL || diskResult.downloadUrl || diskResult.url || '';
const recordingUrl = meta.recordingUrl || diskUrl || '';
return [{ json: { ...meta, recordingUrl, diskFileInfo: diskResult } }];

const norm = $('Normalize Bitrix Payload').first().json ?? {};
const meta = $('Capture Recording Context').first().json ?? {};
const activity = $('Get Activity').first().json.result ?? {};
const deal = $('Get Deal').first().json.result ?? {};
const stat = meta.stat ?? {};
const transcription = $('Transcribe with Local Whisper').first().json ?? {};
const transcript = String(transcription.transcript || transcription.data || transcription.body || '')
  .trim()
  .replace(/\s*(?:Корректор\s+А\.?\s*Егорова\.?)\s*$/iu, '')
  .trim();

if (!transcript) return [];

function cleanId(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function toTimestamp(value) {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return date.toISOString();
}

const communications = Array.isArray(activity.COMMUNICATIONS) ? activity.COMMUNICATIONS : [];
const contactFromActivity = communications.find((item) =>
  String(item.ENTITY_TYPE_ID) === '3' || String(item.ENTITY_TYPE ?? '').toUpperCase() === 'CONTACT'
)?.ENTITY_ID ?? '';
const contactFromOwner = String(activity.OWNER_TYPE_ID) === '3' ? activity.OWNER_ID : '';
const dealId = deal.ID || (String(activity.OWNER_TYPE_ID) === '2' ? activity.OWNER_ID : '');
const contactId = deal.CONTACT_ID || contactFromActivity || contactFromOwner || '';
const employeeId =
  stat.PORTAL_USER_ID || stat.USER_ID || stat.USER_ID_CALL ||
  activity.RESPONSIBLE_ID || activity.AUTHOR_ID || activity.EDITOR_ID || '';
const activityId = cleanId(meta.activityId || norm.activityId || stat.CRM_ACTIVITY_ID || activity.ID);

if (!activityId) throw new Error('Cannot store a call without activity_id');

const callDate = activity.END_TIME || activity.START_TIME || stat.CALL_START_DATE || norm.eventDate;
const row = {
  activity_id: activityId,
  call_datetime: toTimestamp(callDate),
  employee_id: cleanId(employeeId),
  stage_id: cleanId(deal.STAGE_ID),
  deal_id: cleanId(dealId),
  contact_id: cleanId(contactId),
  transcript,
  transcript_model: 'large-v3-turbo',
  source_workflow_id: String($workflow.id),
  source_execution_id: String($execution.id),
  inserted_at: new Date().toISOString(),
};

return [{ json: { row } }];

